import{_ as t,o,c as n,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Version 1.0.0.32 Launched","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.32-launched.md","filePath":"change-log/release/version-1.0.0.32-launched.md"}'),s={name:"change-log/release/version-1.0.0.32-launched.md"};function i(a,e,l,d,g,c){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="version-1-0-0-32-launched" tabindex="-1">Version 1.0.0.32 Launched <a class="header-anchor" href="#version-1-0-0-32-launched" aria-label="Permalink to &quot;Version 1.0.0.32 Launched&quot;">​</a></h1><p>19th September 2025</p><hr><p><strong>Major Features</strong></p><p><strong>Version Upgrade</strong></p><ul><li><strong>Core Version</strong>: Upgraded to <code>1.0.0.32</code></li><li><strong>Order Status</strong>: Fixes applied for both Live Mode and Analyzer Mode</li><li><strong>New Broker Integration</strong>: <strong>Definedge Securities</strong> fully supported</li><li><strong>New Strategy Hosting</strong>: Introduced <code>/python</code> web page where users can directly host and run Python strategies inside Tradeboard</li></ul><hr><h4 id="broker-enhancements-fixes" tabindex="-1">Broker Enhancements &amp; Fixes <a class="header-anchor" href="#broker-enhancements-fixes" aria-label="Permalink to &quot;Broker Enhancements &amp; Fixes&quot;">​</a></h4><p><strong>Aliceblue</strong></p><ul><li><strong>WebSocket</strong>: Frontend “subscribe all” stability fix</li><li><strong>Holdings</strong>: Issue with holdings data corrected</li></ul><p><strong>Definedge (New Integration)</strong></p><ul><li><strong>Broker Support</strong>: Added full integration for Definedge Securities</li><li><strong>Order APIs</strong>: Support for place, modify, cancel, cancelAll, and closeAllPositions</li><li><strong>WebSocket</strong>: Implemented, with fixes for multiple client subscription</li><li><strong>Placesmart Orders</strong>: Implemented</li><li><strong>Quotes &amp; Funds</strong>: Data updates and holdings/funds retrieval supported</li><li><strong>HTTPX Pooling</strong>: Shared connection pooling standardized</li></ul><p><strong>Dhan</strong></p><ul><li><strong>Historical Data API</strong>: Fixes applied for date handling</li></ul><p><strong>Dhan Sandbox</strong></p><ul><li><strong>Historical Data API</strong>: Fixed date handling issue specific to sandbox environment</li></ul><p><strong>Fyers</strong></p><ul><li><strong>PNL &amp; LTP</strong>: Calculation and data fixes</li></ul><p><strong>Flattrade</strong></p><ul><li><strong>WebSocket</strong>: Multiple client subscription bug fixed</li></ul><p><strong>Firstock</strong></p><ul><li><strong>WebSocket</strong>: Fixed handling for multiple clients subscribing to the same symbols</li></ul><p><strong>Groww</strong></p><ul><li><strong>WebSocket</strong>: Added quotes streaming</li><li><strong>Depth Data</strong>: Added for NSE, BSE, NFO, and BFO</li><li><strong>BSE Data</strong>: Dedicated update for exchange coverage</li><li><strong>Index Data</strong>: Streaming index support added</li><li><strong>Instrument Type Lookup</strong>: Implemented for indices</li><li><strong>Fixes</strong>: Inconsistent WebSocket behaviour resolved; strike and lot size columns corrected; REST API depth Nonetype bug fixed</li></ul><p><strong>Kotak</strong></p><ul><li><strong>Tradebook</strong>: Transaction type format fixed</li><li><strong>Quotes</strong>: Open Interest field added</li></ul><p><strong>Shoonya</strong></p><ul><li><strong>WebSocket</strong>: Multiple client subscription support fixed</li><li><strong>Basket Orders</strong>: Issues resolved</li><li><strong>Master Contract</strong>: MCX script handling and ZMQ WebSocket cleanup</li></ul><p><strong>Zebu</strong></p><ul><li><strong>Migrated to HTTPX</strong>: Now uses shared connection pooling for efficient requests</li><li><strong>WebSocket Support</strong>: Fully integrated</li><li><strong>Common Index Symbols</strong>: Implemented</li><li><strong>History &amp; PNL Tracker</strong>: Bug fixes applied</li></ul><hr><h4 id="technical-improvements" tabindex="-1">Technical Improvements <a class="header-anchor" href="#technical-improvements" aria-label="Permalink to &quot;Technical Improvements&quot;">​</a></h4><ul><li><strong>Python Strategy Hosting</strong>: New <code>/python</code> web module for hosting custom Python strategies inside Tradeboard</li><li><strong>Statistics Formatting</strong>: Enhanced formatting to preserve integer counts and properly format prices</li><li><strong>Orderbook Refactor</strong>: Orderbook, tradebook, positions, and holdings fetch moved from services layer for clarity</li><li><strong>Docker</strong>: Write permissions updated; Eventlet added in Dockerfile; Python strategy log issue fixed</li><li><strong>Python SDK</strong>: Updated to remove <code>pandas-ta</code> dependency and fix Numba “nopython” warnings</li><li><strong>Installation</strong>: Ubuntu installation scripts updated; EBS config updated</li></ul><hr><h4 id="security-dependencies" tabindex="-1">Security &amp; Dependencies <a class="header-anchor" href="#security-dependencies" aria-label="Permalink to &quot;Security &amp; Dependencies&quot;">​</a></h4><ul><li><strong>Security Audit</strong>: Hidden vulnerabilities audit completed</li><li><strong>Libraries</strong>: <ul><li><code>tradeboard-python</code> updated to <code>1.0.30</code></li><li><code>httpx</code> pooling standardized across brokers</li><li>Removed <code>pandas-ta</code> dependency</li></ul></li></ul><hr><h4 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h4><ul><li><strong>Readme</strong>: Updated with <code>ping</code> API function and general documentation refresh</li><li><strong>Design Docs</strong>: Updated to reflect new broker integrations and infrastructure changes</li></ul><hr><h4 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h4><ul><li><strong>WebSocket Clients</strong>: Multiple-subscription changes for <strong>Groww, Definedge, Shoonya, Firstock, Flattrade, Zebu</strong> – may require client-side adjustments</li><li><strong>Python SDK</strong>: Removal of <code>pandas-ta</code> requires strategy developers to migrate to supported indicator libraries (<code>pandas_ta</code> or <code>talib</code>)</li></ul><hr><h4 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h4><ul><li><strong>New</strong>: Eventlet (Docker runtime)</li><li><strong>Updated</strong>: <code>tradeboard-python</code> 1.0.30, <code>httpx</code> pooled connections</li><li><strong>Removed</strong>: <code>pandas-ta</code></li></ul><hr><p><strong>Upgrade Instructions</strong></p><p>See <a href="https://docs.algo.wesoftcorp.com/getting-started/upgrade" target="_blank" rel="noreferrer">UPGRADE</a> for detailed steps.</p><p><strong>Migration Notes</strong></p><ul><li>No database migration required in this release.</li><li>WebSocket users (Groww, Definedge, Shoonya, Firstock, Flattrade, Zebu) must test subscription logic.</li><li>Strategy developers: Update indicators if you depended on <code>pandas-ta</code>.</li></ul><p><strong>Support</strong></p><ul><li><strong>Issues</strong>: Report via GitHub Issues.</li></ul>',52)])])}const h=t(s,[["render",i]]);export{u as __pageData,h as default};
